def moving_average(xs,k):
    if k<=0:
        raise ValueError('k must be positive')
    if k>len(xs):
        return []
    total=sum(xs[:k])
    result=[total/k]
    for i in range(k,len(xs)):
        total += xs[i]-xs[i-k]
        result.append(total/k)
    return result

